const { contextBridge, ipcRenderer, webFrame } = require('electron');

function syncWindowControlInset() {
  try {
    const zoom = Math.max(0.25, webFrame?.getZoomFactor?.() || 1);
    const style = document?.documentElement?.style;
    if (!style) return;
    style.setProperty('--desktop-window-controls-inset', `${(90 / zoom).toFixed(2)}px`);
    style.setProperty('--desktop-zoom-inverse', `${(1 / zoom).toFixed(4)}`);
  } catch {}
}

if (typeof window !== 'undefined') {
  window.addEventListener('DOMContentLoaded', syncWindowControlInset);
  window.addEventListener('resize', syncWindowControlInset);
  window.addEventListener('keyup', syncWindowControlInset);
}
